$src = @"
using System;
using System.Runtime.InteropServices;

public static class H {
  [DllImport("ntdll.dll")]
  public static extern int NtQuerySystemInformation(int cls, IntPtr buf, int len, out int ret);
  [DllImport("ntdll.dll")]
  public static extern int NtQueryObject(IntPtr h, int cls, IntPtr buf, int len, out int ret);
  [DllImport("kernel32.dll", SetLastError=true)]
  public static extern IntPtr OpenProcess(uint access, bool inherit, int pid);
  [DllImport("kernel32.dll", SetLastError=true)]
  public static extern bool CloseHandle(IntPtr h);
  [DllImport("kernel32.dll", SetLastError=true)]
  public static extern bool DuplicateHandle(IntPtr srcProc, IntPtr src, IntPtr dstProc,
      out IntPtr dst, uint access, bool inherit, uint options);
  [DllImport("kernel32.dll")]
  public static extern IntPtr GetCurrentProcess();

  public static int SysInfo(int cls, out IntPtr buf) {
    int len = 1 << 20;
    while (len <= (1 << 26)) {
      buf = Marshal.AllocHGlobal(len);
      int ret;
      int st = NtQuerySystemInformation(cls, buf, len, out ret);
      if (st == 0) return len;
      Marshal.FreeHGlobal(buf);
      buf = IntPtr.Zero;
      if (st != unchecked((int)0xC0000004)) return st;
      len *= 2;
    }
    return -1;
  }
}
"@
Add-Type -TypeDefinition $src -ErrorAction Stop

# --- collect handles ---
$len = 0
$buf = [IntPtr]::Zero
$len = [H]::SysInfo(64, [ref]$buf)   # SystemExtendedHandleInformation
if ($len -le 0) { Write-Output "NtQuerySystemInformation failed: $len"; exit 1 }

$count = [Runtime.InteropServices.Marshal]::ReadInt64($buf, 0)
Write-Output "total handles: $count"
$entrySize = 40
$base = [IntPtr]::Add($buf, 16)

$targets = @()
for ($i = 0; $i -lt $count; $i++) {
  $p = [IntPtr]::Add($base, $i * $entrySize)
  $pid_   = [Runtime.InteropServices.Marshal]::ReadInt64($p, 8)
  $hval   = [Runtime.InteropServices.Marshal]::ReadInt64($p, 16)
  $access = [Runtime.InteropServices.Marshal]::ReadInt32($p, 24)
  $typeIdx= [Runtime.InteropServices.Marshal]::ReadInt16($p, 30)
  $targets += [pscustomobject]@{ Pid=$pid_; Handle=$hval; Access=$access; Type=$typeIdx }
}
[Runtime.InteropServices.Marshal]::FreeHGlobal($buf)

# type index for "File" is normally 36-40; instead of guessing we resolve type name lazily.
$me = [H]::GetCurrentProcess()
$found = @()
$sw = [Diagnostics.Stopwatch]::StartNew()

$byPid = $targets | Group-Object Pid
foreach ($g in $byPid) {
  if ($sw.Elapsed.TotalSeconds -gt 90) { Write-Output "timeout after 90s"; break }
  $procId = [int]$g.Name
  if ($procId -le 4) { continue }
  $hProc = [H]::OpenProcess(0x0040, $false, $procId)   # PROCESS_DUP_HANDLE
  if ($hProc -eq [IntPtr]::Zero) { continue }
  foreach ($t in $g.Group) {
    if ($t.Access -eq 0x0012019F) { continue }   # synchronous pipe: NtQueryObject would hang
    $dup = [IntPtr]::Zero
    $ok = [H]::DuplicateHandle($hProc, [IntPtr]$t.Handle, $me, [ref]$dup, 0, $false, 2)
    if (-not $ok) { continue }
    $tb = [Runtime.InteropServices.Marshal]::AllocHGlobal(4096)
    $ret = 0
    $st = [H]::NtQueryObject($dup, 2, $tb, 4096, [ref]$ret)   # ObjectTypeInformation
    if ($st -eq 0) {
      $nlen = [Runtime.InteropServices.Marshal]::ReadInt16($tb, 0)
      $tname = [Runtime.InteropServices.Marshal]::PtrToStringUni([IntPtr]::Add($tb, 8), $nlen / 2)
      if ($tname -eq 'File') {
        $st2 = [H]::NtQueryObject($dup, 1, $tb, 4096, [ref]$ret)  # ObjectNameInformation
        if ($st2 -eq 0) {
          $nlen2 = [Runtime.InteropServices.Marshal]::ReadInt16($tb, 0)
          if ($nlen2 -gt 0) {
            $oname = [Runtime.InteropServices.Marshal]::PtrToStringUni([IntPtr]::Add($tb, 8), $nlen2 / 2)
            if ($oname -match 'Serial|USBSER|VCP|345F|COM') {
              $pn = try { (Get-Process -Id $procId -ErrorAction Stop).ProcessName } catch { '?' }
              $found += [pscustomobject]@{ Pid=$procId; Name=$pn; Handle=$t.Handle; Object=$oname }
            }
          }
        }
      }
    }
    [Runtime.InteropServices.Marshal]::FreeHGlobal($tb)
    [H]::CloseHandle($dup) | Out-Null
  }
  [H]::CloseHandle($hProc) | Out-Null
}

Write-Output "--- candidate holders ---"
