static int check_file(const char *path, const unsigned char *want, size_t len)
{
  unsigned char buf[512];
  FILE *f = fopen(path, "r");
  if (!f) return -errno;
  size_t n = fread(buf, 1, sizeof(buf), f);
  int rc = n == len && !ferror(f) && !memcmp(buf, want, len) &&
           fgetc(f) == EOF ? 0 : -EIO;
  if (fclose(f) && rc == 0) rc = -EIO;
  return rc;
}

