int cmd_mv(FAR struct nsh_vtbl_s *vtbl, int argc, FAR char **argv)
{
  UNUSED(argc);

  struct stat newstat;
  FAR char *oldpath;
  FAR char *newpath;
  int ret;

  /* Get the full path to the old and new file paths */

  oldpath = nsh_getfullpath(vtbl, argv[1]);
  if (oldpath == NULL)
    {
      nsh_error(vtbl, g_fmtcmdoutofmemory, argv[0]);
      return ERROR;
    }

  newpath = nsh_getfullpath(vtbl, argv[2]);
  if (newpath == NULL)
    {
      nsh_error(vtbl, g_fmtcmdoutofmemory, argv[0]);
      ret = ERROR;
      goto errout_with_oldpath;
    }

  /* If the new path is a directory, we need to move the old file or
   * directory into that directory.
   * For example, mv a b/ becomes mv a b/a
   */

  if (stat(newpath, &newstat) == 0 && S_ISDIR(newstat.st_mode))
    {
      FAR char *destpath;

      destpath = nsh_getdirpath(vtbl, newpath, basename(oldpath));
      if (destpath == NULL)
        {
          nsh_error(vtbl, g_fmtcmdoutofmemory, argv[0]);
          ret = ERROR;
          goto errout_with_newpath;
        }

      ret = rename(oldpath, destpath);
      free(destpath);
    }
  else
    {
      ret = rename(oldpath, newpath);
    }

  if (ret < 0)
    {
      nsh_error(vtbl, g_fmtcmdfailed, argv[0], "rename", NSH_ERRNO);
    }

  /* Free the file paths */

errout_with_newpath:
  nsh_freefullpath(newpath);

errout_with_oldpath:
  nsh_freefullpath(oldpath);
  return ret;
}
