 * Input Parameters:
 *   None
 *
 * Returned Value:
 *   A reference to the task-specific task_info_s structure is return on
 *   success.  NULL would be returned in the event of any failure.
 *
 ****************************************************************************/

static inline_function FAR struct task_info_s *task_get_info(void)
{
  FAR struct tls_info_s *info = tls_get_info();

  return info ? info->tl_task : NULL;
}

#undef EXTERN
#ifdef __cplusplus
}
#endif

#endif /* __INCLUDE_NUTTX_TLS_TASK_H */

 *   Allocate and initialize tls_info_s structure.
 *
 * Input Parameters:
 *   - tcb: The TCB of new task
 *
 * Returned Value:
 *   Zero (OK) on success; a negated errno value on failure.
 *
 ****************************************************************************/

int tls_init_info(FAR struct tcb_s *tcb)
{
  FAR struct tls_info_s *info;
  int ret = OK;

  /* Allocate thread local storage */

  info = up_stack_frame(tcb, tls_info_size());
  if (info == NULL)
    {
      ret = -ENOMEM;
    }
  else
    {
      DEBUGASSERT(info == tcb->stack_alloc_ptr);

      /* Initialize thread local storage */

      up_tls_initialize(info);

      /* Derive tl_size w/o arch knowledge */

      info->tl_size = (uint16_t)((FAR char *)tcb->stack_base_ptr -
                                 (FAR char *)tcb->stack_alloc_ptr);

      /* Attach per-task info in group to TLS */

      info->tl_task = tcb->group->tg_info;

      /* Initialize the starting address of argv to NULL to prevent
       * it from being misused.
       */

      info->tl_argv = NULL;

      /* Thread ID */

      info->tl_tid = tcb->pid;
    }

  return ret;
}

