      ssize_t n;

      if (infinite)
        {
          remain = 1000;
        }
      else
        {
          remain = (int)(deadline - vg_modbus_now_ms());
          if (remain < 0)
            {
              remain = 0;
            }
        }

      pfd.fd      = port->fd;
      pfd.events  = POLLOUT;
      pfd.revents = 0;

      ret = poll(&pfd, 1, remain);
      if (ret < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

